namespace quota_fault {thread_local long remaining=-1;thread_local bool count=false;thread_local size_t calls=0,bytes=0;}
void *operator new(size_t n){if(quota_fault::count){++quota_fault::calls;quota_fault::bytes+=n;}if(quota_fault::remaining>=0&&quota_fault::remaining--==0){quota_fault::remaining=0;throw std::bad_alloc();}if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void *operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
