Scene large_fixture(size_t modules,size_t targets=127){
 Mesh mesh;const Vec3 fan[]={{0,0,0},{-.5f,-.5f,0},{.5f,-.5f,0},{.5f,.5f,0},{-.5f,.5f,0}};const uint32_t triangles[]={0,1,2,0,2,3,0,3,4,0,4,1};
 for(size_t m=0;m<modules;++m){const auto base=uint32_t(mesh.positions.size());for(auto v:fan){mesh.positions.push_back(v+Vec3{(float(m)-float(modules-1)/2)*2,0,0});mesh.normals.push_back({0,0,1});mesh.uv.push_back({(float(m%64)+v.x+.5f)/64,(float(m/64)+v.y+.5f)/64});}for(auto v:triangles)mesh.indices.push_back(base+v);}
 Scene s;auto&o=s.active();o.mesh_active=true;o.painted=std::make_shared<PaintedMesh>(mesh,64);auto d=std::make_shared<DeformationState>(mesh);d->morphs=MorphSet(mesh);auto role=std::make_shared<NormalFrames>();role->origin_vertex_count=uint32_t(mesh.positions.size());role->origin_vertices=mesh.indices;role->normals.assign(mesh.indices.size(),{0,0,1});role->tangents.assign(mesh.indices.size(),{1,0,0,1});auto frames=std::make_shared<NormalFrameSet>();frames->pbr=frames->mtoon=role;
 for(uint32_t i=0;i<targets;++i){d->morphs->targets.push_back({"Target "+std::to_string(i),std::vector<Vec3>(mesh.positions.size())});role->targets.push_back({uint64_t(i+1),std::vector<Vec3>(mesh.indices.size()),std::vector<Vec3>(mesh.indices.size())});frames->targets.push_back({uint64_t(i+1),i,{},{}});frames->current_targets.push_back(i+1);}frames->next_target=targets+1;o.deformation=d;auto origin=std::make_shared<SourceUvOrigin>();origin->paint=o.painted->snapshot();origin->deformation=d;auto binding=std::make_shared<SourceMaterialBindings>();binding->has_mtoon=false;binding->normal_frame=SourceMaterialNormalFrame::OriginalAttributes;binding->normal_frames=frames;binding->uv_origin=origin;o.material_bindings=binding;s.validate();return s;
}
size_t actual_frames(const Scene&s){SourceMaterialArchive materials;detail::PolygonSceneArchive origins;for(const auto&o:s.objects()){if(o.material_bindings)materials.add(o.material_bindings,false);if(o.shape_source)origins.add_origin(o.shape_source,false);if(o.rig_source)origins.add_rig_origin(o.rig_source,false);if(o.polygon)origins.add(o.polygon,false);}for(const auto&o:origins.origins())if(o->material_bindings)materials.add(o->material_bindings,false);NormalFrameArchive frames;for(const auto&b:materials.bindings())if(b->normal_frames)frames.add(b->normal_frames,false);return frames.storage_bytes();}
size_t actual_deformations(const Scene&s){auto j=s.encode();size_t n=j.contains("source_materials")?SourceMaterialArchive::deformation_entries(j.at("source_materials")):0;for(const auto&o:s.objects())if(o.deformation)n+=o.deformation->resource_entries();detail::PolygonSceneArchive origins;for(const auto&o:s.objects()){if(o.shape_source)origins.add_origin(o.shape_source,false);if(o.rig_source)origins.add_rig_origin(o.rig_source,false);if(o.polygon)origins.add(o.polygon,false);}for(const auto&o:origins.origins())if(o->deformation)n+=o->deformation->resource_entries();return n;}
detail::KeyArchiveUsage oracle(const Scene&before,const Scene&after,const detail::SourceKeyDerivation *reuse){const auto &o=after.object(before.active().id);const auto &frames=*o.material_bindings->normal_frames;const auto domain=frames.position_domain;auto usage=detail::preflight_key_archive(before,before.active().id,{domain,frames.storage_bytes()-domain->storage_bytes(),o.deformation->resource_entries(),reuse});check(usage.frame_bytes==actual_frames(after),"Prospective frame pooling matches actual durable current and retained owners");check(usage.deformation_entries==actual_deformations(after),"Prospective deformation count matches actual durable inline before/current entries");return usage;}
ShapeKeyEdit change(const Scene&s,size_t target){ShapeKeyEdit edit;edit.action=ShapeKeyAction::Replace;edit.target=target;edit.positions=s.active().painted->mesh().positions;for(size_t v=0;v<edit.positions.size();++v)edit.positions[v]+=s.active().deformation->morphs->targets[target].delta[v];edit.positions[0].z+=.003f;return edit;}
void small(){
 auto source=fixture(false);auto edit=change(source,0);edit.positions[3].z-=.005f;author_shapekey(source,source.active().id,edit);ShapeKeyEdit mirror;mirror.action=ShapeKeyAction::Mirror;mirror.target=0;mirror.name="Budget mirror";auto mirrored=source;author_shapekey(mirrored,mirrored.active().id,mirror);oracle(source,mirrored,nullptr);
 auto replacement=change(mirrored,1);auto replaced=mirrored;author_shapekey(replaced,replaced.active().id,replacement);oracle(mirrored,replaced,mirrored.active().material_bindings->key_derivation.get());check(replaced.active().shape_source==mirrored.active().shape_source,"Replacement preserves its original named source instead of allocating a new anchor");
 auto shared=mirrored;const auto subject=shared.active().id;const auto other=shared.duplicate(subject);shared.select(subject);auto shared_after=shared;author_shapekey(shared_after,subject,replacement);oracle(shared,shared_after,shared.active().material_bindings->key_derivation.get());check(shared_after.object(other).material_bindings==shared.object(other).material_bindings,"Another object retains its actual old frame owner across replacement");
 // Genuine native identity-colour preparation retains the old key material.
 auto colored=mirrored;auto&o=colored.active();ColorPreparationOptions options;options.resolve_identity=true;auto prepared=prepare_source_colors({o.painted,o.appearance,o.material_bindings,o.deformation,o.material},options);o.painted=prepared.paint;o.material_bindings=prepared.material_bindings;colored.validate();auto color_after=colored;author_shapekey(color_after,color_after.active().id,replacement);oracle(colored,color_after,colored.active().material_bindings->key_derivation.get());check(color_after.active().material_bindings->color_preparation==colored.active().material_bindings->color_preparation,"Actual immutable colour before-history remains distinct from replaced frame root");
 // Exercise authentic first-rig and source placement closures without borrowing
 // another field's authority: capture a complete valid named current state.
 auto retained=mirrored;retained.active().rig_source=capture_polygon_origin(retained,retained.active().id);retained.validate();auto retained_after=retained;author_shapekey(retained_after,retained.active().id,replacement);oracle(retained,retained_after,retained.active().material_bindings->key_derivation.get());
 const auto domain=replaced.active().material_bindings->normal_frames->position_domain;const auto payload=replaced.active().material_bindings->normal_frames->storage_bytes()-domain->storage_bytes();auto plan=detail::KeyArchiveProspect{domain,payload,replaced.active().deformation->resource_entries(),mirrored.active().material_bindings->key_derivation.get()};size_t polls=0;detail::preflight_key_archive(mirrored,mirrored.active().id,plan,[&]{++polls;return false;});const auto exact=mirrored.encode();for(size_t cut:{size_t(1),polls/2,polls}){size_t at=0;check(refuses([&]{detail::preflight_key_archive(mirrored,mirrored.active().id,plan,[&]{return ++at>=cut;});},"cancel")&&mirrored.encode()==exact,"Early middle and late prospective traversal cancellation preserves the source");}check(detail::preflight_key_archive(mirrored,mirrored.active().id,plan).frame_bytes==actual_frames(replaced),"Cancelled preflight has no persistent context and exact retry succeeds");
}
void alias_roundtrip(const std::filesystem::path &out){
 auto source=large_fixture(1,1);source.active().painted->layer_properties("Current metadata differs",true,.37f);source.validate();const auto paint=source.active().painted->encode();ShapeKeyEdit mirror;mirror.action=ShapeKeyAction::Mirror;mirror.target=0;mirror.name="Explicit source alias";author_shapekey(source,source.active().id,mirror);auto j=source.encode();const auto &domain=j.at("source_materials").at("normal_frames").at("position_domains").back();check(domain.at("version")==2&&domain.at("current_alias")=="source","Writer emits domain2 only for an actual source/current geometry owner alias");auto loaded=Scene::decode(j);const auto node=loaded.active().material_bindings->key_derivation;const auto source_geometry=node->before_material()->uv_origin->paint->mesh_owner();check(node->before_paint()->mesh_owner()==source_geometry&&node->position_domain()->current_geometry()==source_geometry,"Owning decode restores the declared genuine source geometry alias");check(loaded.active().painted->encode()==paint&&loaded.encode()==j,"Alias restoration keeps every current Paint metadata byte and exact complete graph");std::filesystem::create_directories(out);source.save(out/"alias2.dsculpt");check(Scene::load(out/"alias2.dsculpt").encode()==j,"Real alias2 native file saves and reopens");
 auto bad=j;bad["source_materials"]["normal_frames"]["position_domains"].back()["current_alias"]="before";check(refuses([&]{Scene::decode(bad);},"declared source geometry alias"),"Unknown alias meaning refuses before authority reconstruction");bad=j;bad["source_materials"]["normal_frames"]["position_domains"].back()["version"]=1;check(refuses([&]{Scene::decode(bad);},"native key domain record"),"Legacy domain1 cannot silently consume alias2 keys");
 bad=j;auto &materials=bad["source_materials"];const auto paint_id=materials["key_derivations"].back()["paint"].get<size_t>();auto &uv=materials["paints"][paint_id]["mesh"]["uv"].get_binary();const auto bits=std::bit_cast<uint32_t>(.008f);for(size_t i=0;i<4;++i)uv[i]=uint8_t(bits>>(8*i));check(refuses([&]{Scene::decode(bad);},"source alias differs"),"Same-sized but different current raster cannot borrow source geometry authority");
 // A true current12/source5 seam has no source alias. Setting the witness is
 // not a shortcut for erasing its independent current partition.
 auto split=fixture(false);auto edit=change(split,0);edit.positions[3].z-=.004f;author_shapekey(split,split.active().id,edit);bad=split.encode();auto &d=bad["source_materials"]["normal_frames"]["position_domains"].back();check(d.at("version")==1&&!d.contains("current_alias"),"Non-alias historical domain1 writer remains unchanged");d["version"]=2;d["current_alias"]="source";check(refuses([&]{Scene::decode(bad);},"source alias differs"),"Actual distinct current/source dimensions reject a fabricated alias witness");
}
void alias_faults(){
 auto source=large_fixture(1,1);source.active().painted->layer_properties("Current metadata",true,.37f);ShapeKeyEdit mirror;mirror.action=ShapeKeyAction::Mirror;mirror.target=0;mirror.name="Alias decoder fault";author_shapekey(source,source.active().id,mirror);const auto before=source.encode();quota_fault::calls=0;quota_fault::count=true;auto positive=Scene::decode(before);quota_fault::count=false;const auto count=quota_fault::calls;check(count>0&&count<50000,"Alias owning decoder has bounded measured standard-C++ allocations");
 for(size_t cut=0;cut<count;++cut){quota_fault::remaining=long(cut);bool denied=false;try{auto candidate=Scene::decode(before);}catch(const std::bad_alloc&){denied=true;}catch(...){quota_fault::remaining=-1;throw;}quota_fault::remaining=-1;if(!denied||source.encode()!=before)throw std::runtime_error("Alias decoder allocation rollback failed at prefix "+std::to_string(cut));}
 auto retry=Scene::decode(before);check(retry.encode()==before,"Every persistent alias decoder denial preserves actual source and exact retry");const auto node=retry.active().material_bindings->key_derivation;check(node->before_paint()->mesh_owner()==node->before_material()->uv_origin->paint->mesh_owner(),"Allocation retry restores real source/current owner identity");std::cout<<"ALIAS_ALLOCATION_PREFIXES "<<count<<"\nPASS "<<checks<<" alias decode fault checks\n";
}
void zero_targets(const std::filesystem::path &out){
 auto source=large_fixture(2500,0);ShapeKeyEdit first;first.name="First native zero";author_shapekey(source,source.active().id,first);auto&o=source.active();SourceUvBakeInput input;input.paint=o.painted;input.current_material=o.material_bindings;input.current_deformation=o.deformation;input.source_vertices=o.painted->mesh().indices;const auto mesh=o.painted->mesh();for(auto v:input.source_vertices){input.target.positions.push_back(mesh.positions[v]);input.target.normals.push_back(mesh.normals[v]);input.target.uv.push_back(mesh.uv[v]);input.target.indices.push_back(uint32_t(input.target.indices.size()));}auto adopted=adopt_source_uv_bake(bake_source_uv(input));o.painted=adopted.paint;o.material_bindings=adopted.material_bindings;o.deformation=adopted.deformation;o.appearance=adopted.appearance;source.validate();auto edit=change(source,0);edit.positions[3].z-=.005f;author_shapekey(source,source.active().id,edit);check(source.active().material_bindings->key_derivation&&source.active().painted->mesh().positions.size()==30000,"Real native Create and UV split establish an owning independent large key domain");
 for(size_t i=1;i<128;++i){ShapeKeyEdit zero;zero.name="Actual zero "+std::to_string(i);try{author_shapekey(source,source.active().id,zero);}catch(const std::exception&e){std::cerr<<"ZERO_CREATE_FAILED target_count="<<i+1<<" message="<<e.what()<<std::endl;throw;}}
 check(source.active().deformation->morphs->targets.size()==128&&actual_frames(source)<64*1024*1024,"128 actual zero/Create keys fit their real payload instead of phantom corner N/T arrays");auto before=source;auto moved=change(source,127);author_shapekey(source,source.active().id,moved);oracle(before,source,before.active().material_bindings->key_derivation.get());auto returned=source;ShapeKeyEdit reset;reset.action=ShapeKeyAction::Replace;reset.target=127;reset.positions=source.active().painted->mesh().positions;author_shapekey(returned,returned.active().id,reset);oracle(source,returned,source.active().material_bindings->key_derivation.get());const auto id=returned.active().material_bindings->normal_frames->current_targets.back();check(target(*returned.active().material_bindings->normal_frames->pbr,id).normals.empty()&&target(*returned.active().material_bindings->normal_frames->pbr,id).tangents.empty(),"Return-to-zero really restores the empty seed N/T presence without a conservative rejection");std::filesystem::create_directories(out);returned.save(out/"128-zero.dsculpt");check(Scene::load(out/"128-zero.dsculpt").encode()==returned.encode(),"Full actual128-slot zero/revert graph saves and reopens under unchanged quotas");
}
void boundary(const std::filesystem::path &out){
 ShapeKeyEdit mirror;mirror.action=ShapeKeyAction::Mirror;mirror.target=0;mirror.name="Near aggregate quota";
 {auto over=large_fixture(1630);const auto before=over.encode();quota_fault::calls=quota_fault::bytes=0;quota_fault::count=true;bool rejected=false;try{author_shapekey(over,over.active().id,mirror);}catch(const std::length_error&e){quota_fault::count=false;rejected=std::string_view(e.what()).find("Prospective retained key frames")!=std::string_view::npos;}quota_fault::count=false;std::cout<<"EARLY_QUOTA bytes="<<quota_fault::bytes<<" calls="<<quota_fault::calls<<std::endl;check(rejected&&quota_fault::bytes<8*1024*1024&&over.encode()==before,"Just-over aggregate frame limit refuses before large target copies with exact rollback");}
 {auto before=large_fixture(1629);auto after=before;author_shapekey(after,after.active().id,mirror);auto usage=oracle(before,after,nullptr);check(usage.frame_bytes==134170956&&usage.frame_bytes<128*1024*1024,"Actual near-cap accepted graph is 46772 bytes below unchanged frame limit");std::filesystem::create_directories(out);after.save(out/"near-cap.dsculpt");check(Scene::load(out/"near-cap.dsculpt").encode()==after.encode(),"Near-cap native key graph really saves and reopens");auto edit=change(after,127);auto replaced=after;author_shapekey(replaced,replaced.active().id,edit);auto replacement=oracle(after,replaced,after.active().material_bindings->key_derivation.get());check(replacement.frame_bytes==usage.frame_bytes,"Near-cap replacement drops only obsolete current frames and remains accepted");auto shared=after;const auto id=shared.active().id;shared.duplicate(id);shared.select(id);shared.validate();const auto exact=shared.encode();quota_fault::calls=quota_fault::bytes=0;quota_fault::count=true;bool rejected=false;try{author_shapekey(shared,id,edit);}catch(const std::length_error&e){quota_fault::count=false;rejected=std::string_view(e.what()).find("Prospective retained key frames")!=std::string_view::npos;}quota_fault::count=false;check(rejected&&quota_fault::bytes<8*1024*1024&&shared.encode()==exact,"Same replacement refuses early when another actual object retains the old current frames");}
}
