int main(int argc,char**argv)try{if(argc!=3)return 2;if(std::string_view(argv[1])=="small")small();else if(std::string_view(argv[1])=="large")boundary(argv[2]);else if(std::string_view(argv[1])=="zeros")zero_targets(argv[2]);else if(std::string_view(argv[1])=="alias")alias_roundtrip(argv[2]);else if(std::string_view(argv[1])=="alias-faults")alias_faults();else return 2;std::cout<<"PASS "<<checks<<" prospective archive checks"<<std::endl;return 0;}catch(const std::exception&e){quota_fault::remaining=-1;quota_fault::count=false;std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
